import BaseConfigSheet from "../api/base-config-sheet.mjs";

const { BooleanField } = foundry.data.fields;

/**
 * Configuration application for an actor's initiative.
 */
export default class InitiativeConfig extends BaseConfigSheet {

  /** @override */
  static DEFAULT_OPTIONS = {
    position: {
      width: 420
    }
  };

  /* -------------------------------------------- */

  /** @override */
  static PARTS = {
    config: {
      template: "systems/dndestiny/templates/actors/config/initiative-config.hbs"
    }
  };

  /* -------------------------------------------- */
  /*  Properties                                  */
  /* -------------------------------------------- */

  /** @override */
  get title() {
    return _loc("DND5E.Initiative");
  }

  /* -------------------------------------------- */
  /*  Rendering                                   */
  /* -------------------------------------------- */

  /** @inheritDoc */
  async _preparePartContext(partId, context, options) {
    context = await super._preparePartContext(partId, context, options);
    const source = this.document._source;

    const defaultAbility = CONFIG.DND5E.abilities[CONFIG.DND5E.defaultAbilities.initiative];
    context.abilityOptions = [
      { value: "", label: _loc("DND5E.DefaultSpecific", { default: defaultAbility.label.toLowerCase() }) },
      { rule: true },
      ...Object.entries(CONFIG.DND5E.abilities).map(([value, { label }]) => ({ value, label }))
    ];
    context.data = source.system.attributes.init;
    context.fields = this.document.system.schema.fields.attributes.fields.init.fields;

    const ability = this.document.system.attributes.init.ability || CONFIG.DND5E.defaultAbilities.initiative;
    const abilityConfig = CONFIG.DND5E.abilities[ability];
    context.ability = {
      label: _loc("DND5E.AbilityCheckConfigure", { ability: abilityConfig.label }),
      global: {
        field: this.document.system.schema.fields.rolls?.fields.ability.fields.check.fields.bonus,
        name: "system.rolls.ability.check.bonus",
        value: source.system.rolls?.ability?.check?.bonus
      },
      local: {
        field: this.document.system.schema.fields.abilities.model.fields.check.fields.roll.fields.bonus,
        name: `system.abilities.${ability}.check.roll.bonus`,
        value: source.system.abilities[ability]?.check.roll.bonus
      }
    };

    context.flags = {
      alert: {
        field: new BooleanField({ label: _loc("DND5E.FlagsAlert") }),
        name: "flags.dndestiny.initiativeAlert",
        value: source.flags.dndestiny?.initiativeAlert
      }
    };

    return context;
  }
}
