import SubclassFlow from "../../applications/advancement/subclass-flow.mjs";
import { SubclassValueData } from "../../data/advancement/subclass-data.mjs";
import Advancement from "./advancement.mjs";

/**
 * @import { SubclassAdvancementApplicationData } from "./_types.mjs";
 */

/**
 * Advancement that allows the player to select a subclass for their class. Only allowed on class items
 * and can only be taken once.
 */
export default class SubclassAdvancement extends Advancement {

  /** @inheritDoc */
  static get metadata() {
    return foundry.utils.mergeObject(super.metadata, {
      dataModels: {
        value: SubclassValueData
      },
      order: 70,
      icon: "icons/skills/trades/mining-pickaxe-yellow-blue.webp",
      typeIcon: "systems/dndestiny/icons/svg/subclass.svg",
      title: _loc("DND5E.ADVANCEMENT.Subclass.Title"),
      hint: _loc("DND5E.ADVANCEMENT.Subclass.Hint"),
      apps: {
        flow: SubclassFlow
      }
    });
  }

  /* -------------------------------------------- */
  /*  Display Methods                             */
  /* -------------------------------------------- */

  /** @inheritdoc */
  configuredForLevel(level) {
    return !foundry.utils.isEmpty(this.value);
  }

  /* -------------------------------------------- */

  /** @inheritdoc */
  summaryforLevel(level, { configMode=false }={}) {
    const subclass = this.item.subclass;
    if ( configMode || !subclass ) return "";
    return subclass.toAnchor().outerHTML;
  }

  /* -------------------------------------------- */
  /*  Editing Methods                             */
  /* -------------------------------------------- */

  /** @inheritDoc */
  static availableForItem(item) {
    return !item.advancement.byType.Subclass?.length;
  }

  /* -------------------------------------------- */
  /*  Application Methods                         */
  /* -------------------------------------------- */

  /** @inheritDoc */
  async apply(level, { retainedData={}, uuid }={}, options={}) {
    if ( options.initial ) return;

    const useRetained = uuid === foundry.utils.getProperty(retainedData, "flags.dndestiny.sourceId");
    let itemData = useRetained ? retainedData : null;
    if ( !itemData ) {
      itemData = await this.createItemData(uuid);
      delete itemData.flags?.dndestiny?.advancementOrigin;
      delete itemData.flags?.dndestiny?.advancementRoot;
      foundry.utils.setProperty(itemData, "system.classIdentifier", this.item.identifier);
    }
    if ( itemData ) {
      this.actor.updateSource({ items: [itemData] });
      this.updateSource({ value: { document: itemData._id, uuid: uuid } });
    }
  }

  /* -------------------------------------------- */

  /** @inheritdoc */
  async restore(level, data, options={}) {
    if ( !data ) return;
    this.actor.updateSource({ items: [data] });
    this.updateSource({
      value: {
        document: data._id, uuid: data._stats?.compendiumSource ?? data.flags?.dndestiny?.sourceId
      }
    });
  }

  /* -------------------------------------------- */

  /** @inheritdoc */
  async reverse(level, options={}) {
    const item = this.value.document ?? this.item.subclass;
    if ( !item ) return;
    this.actor.items.delete(item.id);
    this.updateSource({ value: { document: null, uuid: null } });
    return item.toObject();
  }
}
