import Advancement from "./advancement.mjs";
import ScaleValueConfig from "../../applications/advancement/scale-value-config.mjs";
import ScaleValueFlow from "../../applications/advancement/scale-value-flow.mjs";
import { ScaleValueConfigurationData, TYPES } from "../../data/advancement/scale-value-data.mjs";
import { formatIdentifier } from "../../utils.mjs";

/**
 * Advancement that represents a value that scales with class level. **Can only be added to classes or subclasses.**
 */
export default class ScaleValueAdvancement extends Advancement {

  /** @inheritDoc */
  static get metadata() {
    return foundry.utils.mergeObject(super.metadata, {
      dataModels: {
        configuration: ScaleValueConfigurationData
      },
      order: 60,
      icon: "icons/sundries/gaming/dice-pair-white-green.webp",
      typeIcon: "systems/dndestiny/icons/svg/scale-value.svg",
      title: _loc("DND5E.ADVANCEMENT.ScaleValue.Title"),
      hint: _loc("DND5E.ADVANCEMENT.ScaleValue.Hint"),
      multiLevel: true,
      apps: {
        config: ScaleValueConfig,
        flow: ScaleValueFlow
      }
    });
  }

  /* -------------------------------------------- */

  /**
   * The available types of scaling value.
   * @enum {ScaleValueType}
   */
  static TYPES = TYPES;

  /* -------------------------------------------- */

  /** @inheritDoc */
  static localize() {
    super.localize();
    Object.values(TYPES).forEach(v => foundry.helpers.Localization.localizeDataModel(v));
  }

  /* -------------------------------------------- */
  /*  Instance Properties                         */
  /* -------------------------------------------- */

  /** @inheritDoc */
  get levels() {
    return Array.from(Object.keys(this.configuration.scale).map(l => Number(l)))
      .filter(l => !["class", "subclass"].includes(this.item.type) ? true : l !== 0);
  }

  /* -------------------------------------------- */

  /**
   * Identifier for this scale value, either manual value or the slugified title.
   * @type {string}
   */
  get identifier() {
    return this.configuration.identifier || formatIdentifier(this.name);
  }

  /* -------------------------------------------- */
  /*  Display Methods                             */
  /* -------------------------------------------- */

  /** @override */
  displayValueForLevel(level) {
    return this.valueForLevel(level)?.display ?? null;
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  titleForLevel(level, { configMode=false, legacyDisplay=false }={}) {
    const value = this.valueForLevel(level)?.display;
    if ( (!value && (value !== 0)) || !legacyDisplay ) return this.name;
    return `${this.name}: <strong>${value}</strong>`;
  }

  /* -------------------------------------------- */

  /**
   * Scale value for the given level.
   * @param {number} level           Level for which to get the scale value.
   * @returns {ScaleValueType|null}  Scale value at the given level or null if none exists.
   */
  valueForLevel(level) {
    const TypeClass = this.constructor.TYPES[this.configuration.type];
    if ( !TypeClass ) return null;
    const validKeys = Object.keys(TypeClass.schema.fields);
    const data = {};
    for ( const [key, value] of Object.entries(this.configuration.scale).reverse() ) {
      if ( Number(key) > level ) continue;
      validKeys.forEach(k => (data[k] ??= value[k]));
    }
    return foundry.utils.isEmpty(data) ? null : new TypeClass(data, { parent: this });
  }

  /* -------------------------------------------- */

  /**
   * Compare two scaling values and determine if they are equal.
   * @param {*} a
   * @param {*} b
   * @returns {boolean}
   */
  testEquality(a, b) {
    foundry.utils.logCompatibilityWarning(
      "`ScaleValueAdvancement#testEquality` has been deprecated without replacement.",
      { since: "DnD5e 6.0", until: "DnD5e 6.2" }
    );
    const keys = Object.keys(a ?? {});
    if ( keys.length !== Object.keys(b ?? {}).length ) return false;
    for ( const k of keys ) {
      if ( a[k] !== b[k] ) return false;
    }
    return true;
  }

  /* -------------------------------------------- */
  /*  Application Methods                         */
  /* -------------------------------------------- */

  /** @override */
  async automaticApplicationValue(level) {
    return {};
  }

  /* -------------------------------------------- */
  /*  Event Listeners and Handlers                */
  /* -------------------------------------------- */

  /** @inheritDoc*/
  getContextMenuOptions() {
    const options = super.getContextMenuOptions();
    options.push({
      label: "DND5E.ADVANCEMENT.ScaleValue.Action.CopyFormula",
      icon: "fa-solid fa-copy",
      group: "copy",
      onClick: () => {
        const value = `@scale.${this.item.identifier}.${this.identifier}`;
        game.clipboard.copyPlainText(value);
        ui.notifications.info("DND5E.Copied", { console: false, format: { value } });
      }
    });
    return options;
  }
}
